//! Une fiche explicite par capacité ; le test du catalogue refuse les fiches manquantes.
use super::documentation_examples::{ExampleReference::*, Guide};
use serde_json::json;

pub(super) fn guide(id: &str) -> Option<Guide> {
    Some(match id {
        "document.new" => Guide::new("Choose a creatable type and supplied model from discovery. Initial values and signature are explicit; no personal profile is loaded. A new or replacement document gets a new identity. Replacing dirty work requires discard_changes.", json!({"type":"courrier","model":"courrier.model.personal"})),
        "document.open" => Guide::new("Open the last saved archive. Writable opening reserves a cooperative writer lock; read_only=true reads a snapshot without that lock or another session's unsaved edits. Save_as a separate writable copy to edit a read-only snapshot. Replacing dirty work requires discard_changes.", json!({"path":"letter.typsto","read_only":true})).restrict("Explicit file permissions apply. An editable open needs read and write access; a global read-only server only permits read_only=true. A locked writer is never silently replaced."),
        "document.close" => Guide::new("Close the active document and release its cooperative lock. Dirty work is refused unless discard_changes=true. A successful close invalidates the former document reference.", json!({"discard_changes":false})),
        "document.save" => Guide::new("Atomically save to the explicit or current path, preserving editing history. A file changed outside the session is refused by fingerprint. A different existing destination requires save_as with an explicit overwrite decision.", json!({})).restrict("Requires write permission and a path. A read-only original cannot be overwritten; save_as a different copy instead."),
        "document.save_as" => Guide::new("Save atomically to an explicit destination, taking its writer lock. overwrite=true permits replacing an existing file but never bypasses an active lock. Saving a read-only snapshot to a different path creates an editable copy.", json!({"path":"copy.typsto","overwrite":false})),
        "document.export" => Guide::new("Export current in-memory content into a new or empty directory as pdf, typst or both. Typst sources include retained resources, packages and required fonts for autonomy. page_images defaults to true. Export never saves or clears dirty state.", json!({"directory":"export","format":"both","page_images":false})).restrict("Requires export fields and write permission. Separate from batches; an IO failure may leave partial files, which are never overwritten by a retry."),
        "document.set_model" => Guide::new("Validate and install a UTF-8 Typst model from source or path in one undoable change. It must implement the active type; choosing a model changes presentation only. Prefer supplied named model commands where available.", json!({"model":{"kind":"path","path":"model.typ"}})).restrict("Path imports require read permission. Dependencies must already be embedded or supplied locally by the application; no network download or implicit neighboring-file import."),
        "courrier.model.personal" => Guide::new("Apply the supplied personal-letter presentation to a letter. Document content and type are preserved; model page/marker policy is applied by the same validated model operation.", json!({})).restrict("Only for courrier. Fixed page policy is enforced; this does not create a new document or save it."),
        "metadata.set" => Guide::new("Set a field listed by the document type; field IDs are independent of UI language. Dates are fixed ISO YYYY-MM-DD values. Empty draft fields may be valid even when required for export. input=discrete is the default; typing may group adjacent edits.", json!({"field":"letter.subject","value":"Demande de renseignements"})).restrict("The field must belong to the active type. Use document_types.describe or metadata.get for field definitions and export requirements."),
        "document.set_option" => Guide::new("Set paper, landscape, document language or bullet_marker while enforcing the current model's policy. A null bullet_marker restores the model's automatic language-dependent choice. UI language is independent.", json!({"option":{"key":"language","value":"fr"}})).restrict("A model may fix page size/orientation or allowed markers. Invalid or disallowed options are refused rather than silently changing the model."),
        "document.batch" => Guide::new("Execute bounded steps on an evolving private draft. Failure, including final-save failure, publishes no edits. Success is one undo transaction; save is optional and explicit, export is separate. Step guards must match each draft revision or be supplied by a resolving adapter.", json!({"steps":[{"id":"letter.insert_postscript","params":{}},{"id":"text.insert","params":{"text":"Une précision."}}]})).restrict("1–256 allowed editing/selection steps, bounded parameters and resources. No nested batches, file lifecycle, export or recovery steps. An undo changes memory, not an earlier disk save."),
        "text.insert" => Guide::new("Insert literal prose at the target, replacing its selection. A single newline is a space in the same paragraph; two newlines create a paragraph. Use dedicated tools for styles and structures. input_rules=typing enables editor shorthand rules; literal is the predictable default.", json!({"text":"Bonjour Élodie.\n\nUn nouveau paragraphe.","input_rules":"literal"})).restrict("Selections must respect protected text zones. Use annotation navigation for captions/attributions and term/definition navigation for description items."),
        "text.delete" => Guide::new("Delete the selected editable text within validated structural boundaries. An empty selection deletes no text. Use image.remove for a whole image block and caption.", json!({"target":{"kind":"current"}})).restrict("A selection crossing protected cell/zone boundaries is refused. This does not mean a keyboard Backspace or Delete movement."),
        "text.select" => Guide::new("Select a target or move to part=body, annotation, term or definition of its structure. annotation addresses an image caption or quote attribution; term and definition address a description item. Selection does not change content or add history.", json!({"part":"annotation"})).restrict("Choose a compatible structure first; ordinary paragraphs have no annotation. Explicit targets retain their guard."),
        "text.bold" | "text.italic" => Guide::new("Use value=on or off for deterministic formatting, or toggle (default). A nonempty target changes text style; an empty target changes the subsequent typing style. It does not change the Typst model.", json!({"target":{"kind":"all"},"value":"on"})),
        "text.clear" => Guide::new("Remove inline bold, italic and link formatting from the target, or reset subsequent typing style at an empty target. Paragraph/heading/list structure is preserved.", json!({"target":{"kind":"all"}})),
        "text.link" => Guide::new("Apply an explicit URL to a selected visible label. The label remains editable text; this operation does not visit or fetch the URL.", json!({"target":{"kind":"current"},"url":"https://example.org"})).restrict("Requires nonempty text contained in one paragraph and a valid URL; protected boundaries remain enforced."),
        "text.remove_link" => Guide::new("Remove link formatting from selected text while preserving its label and other inline styles. It does not delete linked content or access the URL.", json!({"target":{"kind":"current"}})).restrict("Requires a nonempty compatible text selection."),
        "block.paragraph" => Guide::new("Convert targeted editable paragraphs to ordinary paragraphs, removing their structural heading/list role while preserving text and inline styles.", json!({"target":{"kind":"current"}})),
        "block.heading_1" => Guide::new("Convert targeted paragraphs to level-one headings. The editor's representation is independent of the model, which defines the final heading presentation.", json!({"target":{"kind":"current"}})),
        "block.heading_2" => Guide::new("Convert targeted paragraphs to level-two headings, preserving text and inline styles; the model defines final presentation.", json!({"target":{"kind":"current"}})),
        "block.heading_3" => Guide::new("Convert targeted paragraphs to level-three headings, preserving text and inline styles; the model defines final presentation.", json!({"target":{"kind":"current"}})),
        "block.bullet" => Guide::new("Convert targeted paragraphs to unordered list items. The marker is governed by the model/document option and document language, not by a literal bullet inserted into the text.", json!({"target":{"kind":"current"}})),
        "block.numbered" => Guide::new("Convert targeted paragraphs to ordered list items. Numbering is structural and rendered by Typst; insert ordinary item text rather than literal numbering.", json!({"target":{"kind":"current"}})),
        "block.description" => Guide::new("Create description-list items with separate term and definition zones. Move with text.select part=term or definition and insert literal text into the chosen zone.", json!({"target":{"kind":"current"}})).restrict("Term/definition boundaries are protected. A tab or line break is a structural action rather than arbitrary content inside every zone."),
        "block.quote" => Guide::new("Convert targeted paragraphs to a block quotation, with optional attribution. Move with text.select part=annotation to edit attribution, or body to return to the quote. The model controls final presentation.", json!({"target":{"kind":"current"}})),
        "block.split" => Guide::new("Perform the structural Return action in a quote, list item, description or letter note: split at the target, create the next item, or exit an empty item/optional annotation as appropriate.", json!({"target":{"kind":"current"}})).restrict("Requires a compatible structured block and a valid zone; use text.insert for literal prose and block.exit for an explicit paragraph after a structure."),
        "block.exit" => Guide::new("Create an ordinary paragraph after the targeted quote, image or letter note without replacing its content, then place the caret there.", json!({"target":{"kind":"current"}})).restrict("Requires a structure supported by this navigation operation; incompatible targets are refused."),
        "insert.image" => Guide::new("Insert an image with optional literal one-line caption and alternative text. The caption is a logical annotation; use text.select part=annotation to edit it. The model determines final figure presentation.", json!({"image":{"kind":"embedded","extension":"svg","data":"PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSIxIiBoZWlnaHQ9IjEiLz4="},"alt":"Description de l’image","caption":"Légende facultative"})).restrict("Requires a valid object insertion point. Path variants require read permission; size/format/resource budgets apply. Assets remain in undo memory but only retained resources are saved/exported."),
        "image.replace" => Guide::new("Replace the selected image resource in one undoable change, preserving caption and alternative text. The former resource remains available to undo.", json!({"target":null,"image":{"kind":"embedded","extension":"svg","data":"PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSIxIiBoZWlnaHQ9IjEiLz4="}})).bind("/target", ImageBlock),
        "image.remove" => Guide::new("Remove an image block and its caption as one undoable edit. The resource is omitted from saved/exported files when no longer used by document or model; undo can restore it.", json!({"target":null})).bind("/target", ImageBlock),
        "image.set_alt" => Guide::new("Set alternative text on an existing image without changing its resource or caption. The target must be a current image block, not a character offset.", json!({"target":null,"alt":"Une description accessible de l’image"})).bind("/target", ImageBlock),
        "document.set_signature" => Guide::new("Set a letter signature from an embedded image or permitted file, or remove its image with image=null. Removing the image preserves the model's space for a handwritten signature. No personal preferences are loaded implicitly.", json!({"image":null})).restrict("Only for courrier. Image budgets and path read permissions apply; the change is undoable and not automatically saved."),
        "letter.insert_postscript" => Guide::new("Create or select the letter's postscript and move to its body, then use text.insert. Calling it on an existing postscript selects that structure rather than creating a duplicate.", json!({})).restrict("Only for courrier. Use block.exit to continue in an ordinary paragraph."),
        "letter.insert_attachment" => Guide::new("Insert an enclosure mention and move to its text, then use text.insert for the document name. Mentions form a list; they do not embed attachment files.", json!({})).restrict("Only for courrier. No filesystem read is performed merely by mentioning an attachment."),
        "edit.undo" => Guide::new("Restore the previous document edit and selection using shared history. A batch is one history entry. Saving/exporting is not undone; the restored in-memory document may become dirty.", json!({})).restrict("Requires a previous undoable edit. Do not reuse logical targets from before the revision change."),
        "edit.redo" => Guide::new("Reapply the next undone document edit. A new edit after undo clears the redo branch; saving/exporting remains separate.", json!({})).restrict("Requires redo history; refresh targets after revision changes."),
        "search.find" => Guide::new("Find exact literal Unicode text without moving the selection. Matching is case-insensitive by default; no regex or fuzzy search. Results carry expected text and guarded logical targets for later selection/replacement.", json!({"query":"Élodie","case_sensitive":false})).returns("{guard, matches:[{target, text}]}; an empty match list is a successful search."),
        "edit.find_next" | "edit.find_previous" => Guide::new("Select the next/previous exact literal match from the current target, wrapping through the document. This moves the selection without changing text or adding document history.", json!({"query":"Élodie","case_sensitive":false})),
        "edit.replace_current" => Guide::new("Replace a previously returned search occurrence, validating guard, expected text and the same query/case settings. Preserve compatible inline styles and select the next match.", json!({"query":"Élodie","occurrence":null,"replacement":"Camille"})).bind("/occurrence", SearchOccurrence).restrict("Refresh search after edits. A fabricated, stale or mismatched occurrence is refused; protected boundaries remain enforced."),
        "edit.replace_all" => Guide::new("Replace all literal matches from one guarded revision as one undoable transaction. Use the same exact/case settings as search; replacement is literal text.", json!({"query":"Élodie","replacement":"Camille","case_sensitive":false})).restrict("All replacements must respect structural zones. No regex expansion and no partial publication on failure."),
        "spelling.issues" => Guide::new("List suspected spelling errors and dictionary availability for the document language. This neither checks grammar nor corrects text automatically. Personal words are explicit engine configuration; MCP does not load a personal profile.", json!({})).returns("{guard, language, available, issues:[{target, language, word}]}. available=false is distinct from a clean document."),
        "spelling.next" | "spelling.previous" => Guide::new("Select the next/previous suspected spelling issue from the target, wrapping through the document. Selection only; no automatic correction or document history entry.", json!({})).restrict("Requires a supported dictionary and an actual issue; an absent issue is returned as a domain refusal."),
        "spelling.suggestions" => Guide::new("Suggest spelling corrections for an explicit word/language or an existing guarded issue without modifying selection. Suggestions are optional proposals, not a grammar check.", json!({"target":{"kind":"word","language":"fr","word":"bonjor"}})).returns("{language, word, suggestions}; unsupported dictionaries are refused explicitly, and no correction is applied."),
        "spelling.correct" => Guide::new("Replace an actual current spelling issue with the explicit replacement, preserving compatible inline formatting. Only this accepted change is applied.", json!({"issue":null,"replacement":"bonjour"})).bind("/issue", SpellingIssue),
        "spelling.ignore" => Guide::new("Accept the validated issue's word for its language in this document only. The exception is stored with document options and is undoable; no global dictionary is modified.", json!({"issue":null})).bind("/issue", SpellingIssue),
        "spelling.reset" => Guide::new("Clear spelling exceptions for all languages in the active document as an undoable edit. Explicitly configured personal words remain untouched.", json!({})),
        "document.validate" => Guide::new("Validate document, model, assets, dependencies and options without changing content, selection or installing a render. Separate draft validity from fields missing for export; spelling is a different operation.", json!({})).returns("{guard, valid, ready_for_export, diagnostics}; export-field diagnostics identify missing fields separately from draft validity. A negative validation is a successful query with diagnostics."),
        "render.compile" => Guide::new("Synchronously compile this document revision into a cached in-memory Typst render. No rasterization, export, file write or undo entry. Reuse the resulting render reference for geometry at this revision.", json!({})).returns("{guard, render, diagnostics}; render is null on failure or contains reference and page sizes on success. A compilation error is returned as diagnostics."),
        "render.locate" => Guide::new("Map a logical text target to a page point, or a page point to a logical target, without moving selection. Points are Typst points; core page indices start at 0. A point on model decoration may have no editable target.", json!({"render":null,"position":{"direction":"to_preview","target":{"kind":"current"}}})).bind("/render", Render).restrict("Document and render guards must match. A missing location is not a text-selection edit; inspect nullable target/point.").returns("{render, target, point}; target and point may be null when no editable content is located."),
        "render.selection_boxes" => Guide::new("Read page quadrilaterals for a text target on an identified render, in Typst points. Does not change selection or export images. Core page indices start at 0; boxes can span pages.", json!({"render":null,"target":{"kind":"all"}})).bind("/render", Render).returns("{render, boxes}; each box carries a 0-based page index and a quadrilateral in Typst points."),
        "document.statistics" => Guide::new("Count Unicode words and grapheme clusters in committed editable content. Structural markers/private metadata are excluded. An optional target adds selection counts; an omitted target or empty caret has no selection counter.", json!({"target":{"kind":"current"}})).returns("{guard, document, target}; statistics include signs and signs_without_spaces. It never counts a preedit IME draft."),
        "document_types.list" => Guide::new("Discover built-in types, their capabilities, model cards and creation availability without opening a document. A type may exist while can_create=false because no model is supplied.", json!({})).returns("{types:[{id, can_create, models, capabilities}]}; type IDs and capability IDs are technical and stable."),
        "document.source" => Guide::new("Read the committed documentary Typst source with its guard. It is the content source, separate from the model and main composition; reading it does not execute code or change content.", json!({})).returns("{guard, source}. Use text and structure for ordinary composition; do not insert this markup as literal prose."),
        "document.assets" => Guide::new("Inventory assets retained by the document or model, plus embedded dependencies. Returns names and sizes rather than file contents; does not traverse undo snapshots or arbitrary disk paths.", json!({})).returns("{guard, assets:[{path,bytes}], dependencies:[{path,bytes}]}. An unused image still held by undo is absent from the retained inventory."),
        "document.inspect" => Guide::new("Read session state, current guard and selection, type, capabilities, typing style, dirty state, read-only state, path and history availability. Without a document, document context is null. No file is opened by inspecting.", json!({})).returns("A session-state object. In MCP the outer document reference is the value to pass back, distinct from this core guard."),
        "document.text" => Guide::new("Read editable plain text without Typst markup or image object markers. Defaults to all text, unlike editing targets which default to current. A guarded subtarget restricts the read without changing selection.", json!({"target":{"kind":"all"}})).returns("{guard, text}; metadata and model-inserted decorations are not the editable text."),
        "document.structure" => Guide::new("Read ordered blocks with opaque block and text-zone IDs, roles and visible text; image blocks include internal resource path and alternative text. Use IDs with the returned guard, never as character offsets.", json!({})).returns("{guard, blocks:[{id,kind,zones,...}]}. Text-zone roles distinguish body, annotation, term and definition."),
        "metadata.get" => Guide::new("Read active document metadata, options and field definitions/values. Type-defined export requirements are distinct from draft validity. Private fields are explicit document data, not loaded preferences.", json!({})).returns("{guard, metadata, fields}; fields identifies each field's section, kind, value and required_for_export flag."),
        "models.list" => Guide::new("List supplied visual model cards for the active type, indicating which supplied model matches the current presentation. A custom model may match none. A model does not introduce different semantic fields or capabilities.", json!({})).returns("{guard, document_type, models}. MCP exposes only brief visual cards; no model source or technical presentation contract."),
        "models.presentation" => Guide::new("Read the active model's page and bullet-marker policy for an adapter preparing document options. This technical query does not change the model or document.", json!({})).restrict("Not exposed as an MCP tool: agents use interchangeable brief model cards; the engine enforces presentation policy.").returns("{guard, fixed_page, bullet_markers, custom_bullet_marker}."),
        "commands.list" => Guide::new("Read command/query schemas and context availability without executing commands or fabricating missing parameters. Enabled, disabled with reason, and requires_parameters are distinct. Type capability is not the same as current selection availability or adapter authorization.", json!({})).returns("{guard, selection, entries}; MCP adds mcp_support and an effective MCP input schema to each entry."),
        "recovery.list" => Guide::new("List opaque references from an explicitly configured recovery service without opening recovered documents. It never searches arbitrary directories on behalf of an adapter.", json!({})).restrict("Recovery service must be configured. Not exposed by standalone MCP.").returns("{configured, entries}; each entry has an opaque reference, optional name/date and diagnostics."),
        "recovery.restore" => Guide::new("Restore one configured recovery reference as an unsaved independent document, protecting dirty current work unless discard_changes=true. This replaces document identity rather than editing existing text.", json!({"reference":null,"discard_changes":false})).bind("/reference", Recovery).restrict("Requires an existing configured recovery reference. Not exposed by standalone MCP."),
        "recovery.delete" => Guide::new("Explicitly delete one configured recovery copy, without changing document history or the active document. This deletion is not undoable by document editing history.", json!({"reference":null})).bind("/reference", Recovery).restrict("Requires an existing configured recovery reference. Not exposed by standalone MCP."),
        _ => return None,
    })
}
